import sys

def main():
    s = sys.stdin.readline().strip()
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1
    for i in range(26):
        if cnt[i] == 0:
            continue
        cnt[i] -= 1
        vals = {v for v in cnt if v > 0}
        cnt[i] += 1
        if len(vals) <= 1:
            print('true')
            return
    print('false')

main()

